import { expect, test, uniqueName } from "../../fixtures";

const API_TIMEOUT = undefined;

function isoDateFromToday(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

const cases = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
] as const;

test.describe("insurance expiry flag", () => {
  for (const { days, include } of cases) {
    const verb = include ? "include" : "do not include";
    test(
      `vendor whose insurance expires in ${days} days ${verb} insurance_expiring_soon`,
      { tag: "@REV-08" },
      async ({ apiAs }) => {
        // Arrange
        const member = await apiAs("member");
        const createRes = await member.post("/api/vendors", {
          data: {
            name: uniqueName("Expiry Check"),
            category: "logistics",
            contact_email: "ops@expiry-check.example",
          },
        });
        expect(createRes.status(), await createRes.text()).toBe(201);
        const vendor = (await createRes.json()) as { id: string };

        const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "insurance_certificate",
            file: {
              name: "insurance.txt",
              mimeType: "text/plain",
              buffer: Buffer.from(insuranceText(isoDateFromToday(days))),
            },
          },
        });
        expect(uploadRes.status(), await uploadRes.text()).toBe(201);

        // Act
        const res = await member.get(`/api/vendors/${vendor.id}`);

        // Assert
        expect(res.status(), await res.text()).toBe(200);
        const body = (await res.json()) as { flags: string[] };
        if (include) {
          expect(body.flags, `flags for ${days} days`).toContain("insurance_expiring_soon");
        } else {
          expect(body.flags, `flags for ${days} days`).not.toContain("insurance_expiring_soon");
        }
      },
    );
  }
});

export { API_TIMEOUT };
